            float freq = amzp_SEA_FREQ;
            float amp = amzp_SEA_HEIGHT;
            float choppy = amzp_SEA_CHOPPY;
            float2 uv = p.xz; uv.x *= 0.75;
            float d, h = 0.0;
            for(int i = 0; i < 2; i++) {
             d = sea_octave((uv+(amzp_progressa * 2.0))*freq,choppy);
                h += d * amp;
             uv *= octave_m;
                freq *= 1.9;
                amp *= 0.22;
                choppy = mix(choppy,1.0,0.2);
            }
            return p.y - h;
        }
