            float fresnel = 1.0 - max(dot(n,-eye),0.0);
            fresnel = pow(fresnel,3.0) * 0.45;
            float3 reflected = getSkyColor(reflect(eye,n))*0.99;
                  reflected *= amzp_CSKY.rgb;
