            float hm = map(ori + dir * tm);
            float tmid = 0.0;
            for(int i = 0; i < int(amzp_NUM_STEPS); i++) {
                tmid = mix(tm,tx, hm/(hm-hx));
                p = ori + dir * tmid;
             float hmid = map(p);
                if(hmid < 0.0) {
                    tx = tmid;
                    hx = hmid;
                } else {
                    tm = tmid;
                    hm = hmid;
                }
            }
            return tmid;
        }
