            float3 ang = float3(roll,pitch,yaw);
            float3 ori = float3(0.0,3.5,amzLocal_time*3.0);
            float3 dir = normalize(float3(uv.xy,-1.6));
            dir = normalize(dir) * fromEuler(ang);
            float3 p;
            heightMapTracing(ori,dir,p);
            float3 dist = p - ori;
            float3 n = getNormal(p,
                     dot(dist,dist)
                        * (0.5 / screen.zw.x)
                   );
            float3 light = normalize(float3(0.0,1.0,0.8));
         float3 skyColor = getSkyColor(dir);
            float3 seaColor = getSeaColor(p,n,light,dir,dist);
            seaColor /= sqrt(sqrt(length(dist))) ;
            bool night;
            if( (amzp_nmode>0.5) )
            {
             seaColor *= seaColor * 8.5;
             skyColor /= 1.69;
                night = true;
            }
            else
            {
             seaColor *= sqrt(sqrt(seaColor)) * 4.0;
                skyColor *= 1.05;
                skyColor -= 0.03;
                night = false;
            }
            skyColor *= skyColor;
            float3 seaHsv = rgb2hsv(seaColor);
            if (seaHsv.z > .75 && length(dist) < 50.0)
               seaHsv.z -= (0.9 - seaHsv.z) * 1.3;
            seaColor = hsv2rgb(seaHsv);
            float3 color = mix(
                skyColor,
                seaColor,
             pow(smoothstep(0.0,-0.05,dir.y), 0.3)
            );
            fragColor = float4(pow(color,float3(0.75)), 1.0);
            float3 hsv = rgb2hsv(fragColor.xyz);
            hsv.y += 0.131;
            hsv.z *= sqrt(hsv.z) * 1.1;
            if (night)
            {
                hsv.z -= 0.045;
                hsv*=0.8;
                hsv.x += 0.12 + hsv.z/100.0;
                hsv.y *= 2.87;
            }
            else
            {
                hsv.z *= 0.9;
                hsv.x -= hsv.z/10.0;
                hsv.x += 0.02 + hsv.z/50.0;
                hsv.z *= 1.01;
                hsv.y += 0.07;
            }
            fragColor.xyz = hsv2rgb(hsv);
     amzOutput = mix(texColor, fragColor, amzp_alpha) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

