            float2 swv = abs(cos(uv));
            wv = mix(wv,swv,wv);
            return pow(1.0-pow(wv.x * wv.y,0.65),choppy);
        }
        float map(float3 p) {
            float freq = amzp_SEA_FREQ;
            float amp = amzp_SEA_HEIGHT;
            float choppy = amzp_SEA_CHOPPY;
            float2 uv = p.xz; uv.x *= 0.75;
            float d, h = 0.0;
            for(int i = 0; i < 2; i++) {
             d = sea_octave((uv+(amzp_progressa * 2.0))*freq,choppy);
                h += d * amp;
             uv *= octave_m;
                freq *= 1.9;
                amp *= 0.22;
                choppy = mix(choppy,1.0,0.2);
            }
            return p.y - h;
        }
        float map_detailed(float3 p) {
            float freq = amzp_SEA_FREQ;
            float amp = amzp_SEA_HEIGHT;
            float choppy = amzp_SEA_CHOPPY;
            float2 uv = p.xz; uv.x *= 0.75;
            float d, h = 0.0;
            for(int i = 0; i < int(amzp_ITER_FRAGMENT); i++) {
             d = sea_octave((uv+(amzp_progressa * 2.0))*freq,choppy);
             d += sea_octave((uv-(amzp_progressa * 2.0))*freq,choppy);
                h += d * amp;
             uv *= octave_m/1.2;
                freq *= 1.9;
                amp *= 0.22;
                choppy = mix(choppy,1.0,0.2);
            }
            return p.y - h;
        }
        float3 getSeaColor(float3 p, float3 n, float3 l, float3 eye, float3 dist) {
            float fresnel = 1.0 - max(dot(n,-eye),0.0);
            fresnel = pow(fresnel,3.0) * 0.45;
            float3 reflected = getSkyColor(reflect(eye,n))*0.99;
                  reflected *= amzp_CSKY.rgb;
            float3 refracted = amzp_SEA_BASE.rgb + diffuse(n,l,80.0) * amzp_SEA_WATER_COLOR.rgb * 0.27;
            float3 color = mix(refracted,reflected,fresnel);
            float atten = max(1.0 - dot(dist,dist) * 0.001, 0.0);
            color += amzp_SEA_WATER_COLOR.rgb * (p.y - amzp_SEA_HEIGHT) * 0.15 * atten;
            color += float3(specular(n,l,eye,90.0))*0.5;
            return color;
        }
        float3 getNormal(float3 p, float eps) {
            float3 n;
            n.y = map_detailed(p);
            n.x = map_detailed(float3(p.x+eps,p.y,p.z)) - n.y;
            n.z = map_detailed(float3(p.x,p.y,p.z+eps)) - n.y;
            n.y = eps;
            return normalize(n);
        }
        float isKeyPressed(float key)
        {
         return amzTexture( 0, float2(key, 1.0) ).x;
        }
        float heightMapTracing(float3 ori, float3 dir, out float3 p) {
            float tm = 0.0;
            float tx = 500.0;
            float hx = map(ori + dir * tx);
            if(hx > 0.0) return tx;
            float hm = map(ori + dir * tm);
            float tmid = 0.0;
            for(int i = 0; i < int(amzp_NUM_STEPS); i++) {
                tmid = mix(tm,tx, hm/(hm-hx));
                p = ori + dir * tmid;
             float hmid = map(p);
                if(hmid < 0.0) {
                    tx = tmid;
                    hx = hmid;
                } else {
                    tm = tmid;
                    hm = hmid;
                }
            }
            return tmid;
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float2 satriyaid;
        if ((amzp_adaptive>0.5)) {
        satriyaid = amzScreenNorm();
        }
        else {
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        }
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
     float4 fragColor;
            float2 uv = satriyaid;
            uv = uv * 2.0 - 1.0;
            uv.x *= screen.zw.x / screen.zw.y;
            float amzLocal_time = amzp_camprog * 2.7;
            float roll = PI + amzp_progressc ;
            float pitch = PI*1.021 + (sin(1.0/2.0)+ cos(1.0))/40.0
                + ((200.+amzp_camy)/screen.zw.y - .8)*PI/3.0 ;
            float yaw = amzp_camx/screen.zw.x * PI * 4.0;
            float3 ang = float3(roll,pitch,yaw);
            float3 ori = float3(0.0,3.5,amzLocal_time*3.0);
            float3 dir = normalize(float3(uv.xy,-1.6));
            dir = normalize(dir) * fromEuler(ang);
            float3 p;
            heightMapTracing(ori,dir,p);
            float3 dist = p - ori;
            float3 n = getNormal(p,
                     dot(dist,dist)
                        * (0.5 / screen.zw.x)
                   );
            float3 light = normalize(float3(0.0,1.0,0.8));
         float3 skyColor = getSkyColor(dir);
            float3 seaColor = getSeaColor(p,n,light,dir,dist);
            seaColor /= sqrt(sqrt(length(dist))) ;
            bool night;
            if( (amzp_nmode>0.5) )
            {
             seaColor *= seaColor * 8.5;
             skyColor /= 1.69;
                night = true;
            }
            else
            {
             seaColor *= sqrt(sqrt(seaColor)) * 4.0;
                skyColor *= 1.05;
                skyColor -= 0.03;
                night = false;
            }
            skyColor *= skyColor;
            float3 seaHsv = rgb2hsv(seaColor);
            if (seaHsv.z > .75 && length(dist) < 50.0)
               seaHsv.z -= (0.9 - seaHsv.z) * 1.3;
            seaColor = hsv2rgb(seaHsv);
            float3 color = mix(
                skyColor,
                seaColor,
             pow(smoothstep(0.0,-0.05,dir.y), 0.3)
            );
            fragColor = float4(pow(color,float3(0.75)), 1.0);
            float3 hsv = rgb2hsv(fragColor.xyz);
            hsv.y += 0.131;
            hsv.z *= sqrt(hsv.z) * 1.1;
            if (night)
            {
                hsv.z -= 0.045;
                hsv*=0.8;
                hsv.x += 0.12 + hsv.z/100.0;
                hsv.y *= 2.87;
            }
            else
            {
                hsv.z *= 0.9;
                hsv.x -= hsv.z/10.0;
                hsv.x += 0.02 + hsv.z/50.0;
                hsv.z *= 1.01;
                hsv.y += 0.07;
            }
            fragColor.xyz = hsv2rgb(hsv);
     amzOutput = mix(texColor, fragColor, amzp_alpha) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
